function vcF2() {
    const hooks = globalThis[Symbol.for('virtual-companion.bridge')]?.f2;
    if (!hooks) throw Object.assign(new Error('F2 storage is unavailable'), { status: 503, code: 'VC_F2_UNAVAILABLE' });
